def link_added_people(apps, schema_editor):
    """Turn "added <name>" text into body "added" plus a link to the person."""
    User = apps.get_model("core", "User")
    Message = apps.get_model("chat", "Message")
    people = {}
    for user in User.objects.all():
        people[user.username.lower()] = user
        full_name = f"{user.first_name} {user.last_name}".strip().lower()
        people.setdefault(full_name, user)
    for message in Message.objects.filter(kind="system", body__startswith="added "):
        person = people.get(message.body.removeprefix("added ").lower())
        if person:
            message.body = "added"
            message.subject = person
            message.save(update_fields=["body", "subject"])


